"<h4 class=\"det-sub\">Facebook</h4><p class=\"det-tarea\">{0} Se guarda cifrada.</p>\n  <form class=\"det-form\" data-form=\"fb-app\"><input type=\"text\" name=\"appid\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Identificador de la app\" aria-label=\"Identificador de la app de Meta\" value=\"{1}\"><input type=\"password\" name=\"s\" autocomplete=\"off\" placeholder=\"Clave secreta\" aria-label=\"Clave secreta de la app de Meta\"><button class=\"btn peq\" type=\"submit\">Guardar</button></form>\n  {2}":"<h4 class=\"det-sub\">Facebook</h4><p class=\"det-tarea\">{0} It's stored encrypted.</p>\n  <form class=\"det-form\" data-form=\"fb-app\"><input type=\"text\" name=\"appid\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"App ID\" aria-label=\"Meta app ID\" value=\"{1}\"><input type=\"password\" name=\"s\" autocomplete=\"off\" placeholder=\"Secret key\" aria-label=\"Meta app secret key\"><button class=\"btn peq\" type=\"submit\">Save</button></form>\n  {2}",
