"<div class=\"conexiones\"><div><h3>Conexiones</h3><p class=\"meta\">Los servicios con los que trabaja la oficina. Las claves se guardan cifradas.</p></div>\n    {0}{1}{2}{3}{4}{5}\n    <div class=\"acciones\" style=\"margin-top:16px\"><button class=\"btn sec\" type=\"button\" data-acc=\"cerrar\">Cerrar</button></div></div>":"<div class=\"conexiones\"><div><h3>Connections</h3><p class=\"meta\">The services the office works with. Keys are stored encrypted.</p></div>\n    {0}{1}{2}{3}{4}{5}\n    <div class=\"acciones\" style=\"margin-top:16px\"><button class=\"btn sec\" type=\"button\" data-acc=\"cerrar\">Close</button></div></div>",
